	public class IndiaEInvoiceDataResponseReaderTest : TestCase
	{
		public void TestConstructor()
		{
			AssertExceptionThrown(typeof(ArgumentNullException), "Value cannot be null.\r\nParameter name: payload", () => new IndiaEInvoiceResponseReader(null, null));
			AssertExceptionThrown(typeof(ArgumentException), "Value cannot be empty string (\"\").\r\nParameter name: payload", () => new IndiaEInvoiceResponseReader(string.Empty, null));
			AssertExceptionThrown(typeof(ArgumentNullException), "Value cannot be null.\r\nParameter name: notifications", () => new IndiaEInvoiceResponseReader("some string", null));
			AssertNoExceptionThrown("Correct arguments", () => new IndiaEInvoiceResponseReader("some string", new NotificationBuffer()));
		}

		public void TestRead_EmptyString()
		{
			var notifications = new NotificationBuffer();
			var reader = new IndiaEInvoiceResponseReader(" ", notifications);

			AssertNull(reader.Read());
			Assert(notifications.HasErrors);
			var errors = notifications.GetEventsByType(NotificationType.Error);
			AssertEquals("Expected error count for empty json string", 1, errors.Length);
			AssertContains("Reading the following India E-Invoice Response has failed due to invalid JSON:", errors[0].Message);
		}

