		public void TestRead_MissingRequiredFields()
		{
			// All fields are required in India.
			var requiredFields = new string[]
			{
				"AckNo",
				"AckDt",
				"Irn",
				"SignedInvoice",
				"SignedQRCode",
				"Status",
			};
			var fields = new string[]
			{
				"'AckNo':2",
				"'AckDt':'2019-12-25 12:30:01'",
				"'Irn':'d056a57cc7cfcc6c9230aa0014e439259d0dc57cfa4eea2326253011fd53ea7e'",
				"'SignedInvoice':'eyJhbGciOiJodHRwOi8vd3d3LnczLm9yZy8yMDAxLzA0L3htbGRzaWctbW9yZSNyc2Etc2hhMjU2Iiwia2lkIjoiRTc4MDhFNkZGMDNFMTMyODUzMzBCMDQxQjNFMEEzQUVDNDc4MTMyMCIsInR5cCI6IkpXVCIsIng1dCI6IjU0Q09iX0EtRXloVE1MQkJzLUNqcnNSNEV5QSJ9..II0jejF0wOrY0CPwIb6oQsSBYilvFSNHZqQJHYOsFt7txrpAvLlCEo4CDNUhPZGWZ6IeERuoY2ScXKNIsCIMQR_9dc0E_fmsaN5XUscxBV3nqPNIkusFcmzjxu59sT8MzcaFqDWfqHunkA-klW40M7oVy6HtL5eI0zbmNoZpdl2yB1Fxfx5AF_vcDv9vWV2u6i39XQ0KdTSbkTAVStdXHix2hE0TlHtHB9Tqt7i9umNPJc_Uf5Kpn4qHiOPvFT2uxhw1N7bIU00cc-PDIqzlLk2VnLb2Zko7wSgYAMrf5G1hn5Op4lbyQe9EwxOPcvJPjJBJsoOmFTbxd1IRgewm7g'",
				"'SignedQRCode':'eyJhbGciOiJodHRwOi8vd3d3LnczLm9yZy8yMDAxLzA0L3htbGRzaWctbW9yZSNyc2Etc2hhMjU2Iiwia2lkIjoiRTc4MDhFNkZGMDNFMTMyODUzMzBCMDQxQjNFMEEzQUVDNDc4MTMyMCIsInR5cCI6IkpXVCIsIng1dCI6IjU0Q09iX0EtRXloVE1MQkJzLUNqcnNSNEV5QSJ9..UbnWZAI_lq9s9JK8_MovcmjpMPIJnv2-4qGkiXegggQbry_0fJxjwaR8fwCjK_-HVeMujnw8C7F3ITrxKIg5RsdDMzAvLrCNE0K3QkNHGczbvyxhJ02VRFl1wrQoArxSW1RiyGssLSbH_4tdQ6vke0nSUajXRXvXX2yUeI01CyLsbf2FDNIq46MrDmka5RPNGp0dCx4uX2gkmsCx0Yb0CKjqFI176sTbxOQDHQtRCAfJ0I6dwwggVkfnC3p2F-x6GhEls_7GVsFg1Z6k4A_aB89c3N6CaWfe8DOQEJTjWaPggMUa2-1hDE1ODTBcIlLcOwB-8jT971hZWgtBubUzFg'",
				"'Status':'ACT'",
			};

			foreach (var excludedField in requiredFields)
			{
				var jsonBuilder = new ZStringBuilder();
				foreach (var field in fields)
				{
					if (!field.Contains("'" + excludedField + "'"))
					{
						jsonBuilder.Append(field);
					}
				}

				var incompleteJson = GetJsonString(jsonBuilder);
				var notifications = new NotificationBuffer();
				var reader = new IndiaEInvoiceResponseReader(Convert.ToBase64String(Encoding.UTF8.GetBytes(incompleteJson)), notifications);

				AssertNull("Json object is null when following required part is missing: " + excludedField.Replace("'", "\""), reader.Read());
				Assert(notifications.HasErrors);
				var errors = notifications.GetEventsByType(NotificationType.Error);
				AssertEquals("Expected error count for missing " + excludedField.Replace("'", "\""), 3, errors.Length);
				Assert(errors.Take(2).All(x => x.Message.Contains("Required propert")));
				AssertContains(incompleteJson, errors[2].Message);
			}
		}

