		#region Implementation

		string GetJsonString(string[] fields)
		{
			var jsonBuilder = new ZStringBuilder();
			foreach (var field in fields)
			{
				jsonBuilder.Append(field);
			}
			return GetJsonString(jsonBuilder);
		}

		string GetJsonString(ZStringBuilder jsonBuilder)
			=> ("{" + jsonBuilder.ToStringWithDelimiterBetweenAppends(",") + "}").Replace("'", "\"");

		#endregion
	}
